21	
22	/**
23	 * H2（MODE=MySQL）事务边界测试：验证同一行的真实更新会取得行级排他锁，
24	 * 第二个事务的同行更新必须阻塞至第一个事务提交或回滚。这是审核与禁飞区变更
25	 * 串行化、保证一致状态读取的数据库基础，不使用 mock 代替。
26	 */
27	@SpringBootTest
28	@DisplayName("H2 行级排他锁事务互斥")
29	class H2LockProbeTest {
30	
31	    @Autowired
32	    private DataSource dataSource;
33	    @Autowired
34	    private JdbcTemplate jdbc;
