                "SELECT x, y FROM route_point WHERE route_id = 'r1' ORDER BY seq");
        assertEquals(2, newPoints.size());
        assertEquals(80, ((Number) newPoints.get(0).get("y")).intValue());
        assertEquals(80, ((Number) newPoints.get(1).get("y")).intValue());
